function tax(income, brackets){
  if(!(income>=0)||!Array.isArray(brackets)||!brackets.length) return null;
  var prev=0, total=0;
  for(var i=0;i<brackets.length;i++){
    var up=brackets[i].upTo, rate=brackets[i].rate;
    var upper=(up===Infinity)?income:Math.min(up,income);
    if(upper>prev){ total += (upper-prev)*rate; prev=upper; }
    if(income<=up) break;
  }
  return {tax:total, effective: total/income, marginal: brackets[Math.max(0, bracketIndex(income,brackets))].rate};
}
function bracketIndex(income, brackets){
  var idx=0; for(var i=0;i<brackets.length;i++){ if(income>brackets[i].upTo) idx=i+1; } return Math.min(idx, brackets.length-1);
}
var EXPORTS={tax:tax,bracketIndex:bracketIndex};


